contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 amount) public {
        require(to != address(0), "recipient must be nonzero");
        uint256 balSenderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(amount > balSenderBefore, "amount must exceed sender balance");
        uint256 balToBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balSenderAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 balToAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;

        assert(reverted && balSenderAfter == balSenderBefore && balToAfter == balToBefore);
    }

    receive() external payable {}
}

