    function _run(address to, uint256 amount) internal {
        vm.assume(to != address(0));
        uint256 balSenderBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balSenderBefore = __r; } catch { return; }
        vm.assume(amount > balSenderBefore);
        uint256 balToBefore;
        try c.balanceOf(to) returns (uint256 __r) { balToBefore = __r; } catch { return; }
        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
